package worker
import ("context"; "testing"; "time"; "log/slog"; "github.com/11DingKing/dali-arts-experience-hub/internal/domain"; "github.com/11DingKing/dali-arts-experience-hub/internal/repository"; "github.com/11DingKing/dali-arts-experience-hub/internal/storage/sqlite")
func TestDali017TransactionErrorRollsBack(t *testing.T){s:=newWorkerStore(t);err:=s.WithinTx(context.Background(),func(tx repository.Tx)error{if e:=tx.InsertRegion(context.Background(),domain.Region{ID:"rollback017",Name:"temp",TimeZone:"Asia/Shanghai",Version:1,CreatedAt:time.Now(),UpdatedAt:time.Now});e!=nil{return e};return context.Canceled});if err==nil{t.Fatal("expected callback error")};if err:=s.WithinTx(context.Background(),func(tx repository.Tx)error{return tx.InsertRegion(context.Background(),domain.Region{ID:"rollback017",Name:"again",TimeZone:"Asia/Shanghai",Version:1,CreatedAt:time.Now(),UpdatedAt:time.Now})});err!=nil{t.Fatalf("failed transaction committed data: %v",err)}}